import React, { useRef } from 'react';

function App() {
  const audioRef = useRef(null);
  const joinDiscord = () => {
    if (audioRef.current) {
      audioRef.current.play().catch(() => {});
    }
    window.open('https://discord.gg/nwcrh7uG9y', '_blank');
  };
  // Animation: fade-in on load
  const [visible, setVisible] = React.useState(false);
  React.useEffect(() => {
    setTimeout(() => setVisible(true), 100); // slight delay for effect
  }, []);

  return (
    <>
      <audio ref={audioRef} src="/audio/RobDougan-ClubbedToDeath.mp3" autoPlay loop />
      <div
        style={{
          minHeight: '100vh',
          background: '#393939',
          color: '#e0e0e0', // brighter for readability
          fontFamily: 'Segoe UI, Arial, sans-serif',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          transition: 'opacity 1.2s cubic-bezier(.77,0,.18,1)',
          opacity: visible ? 1 : 0,
        }}
      >
        <div
          style={{
            fontSize: 72,
            fontWeight: 700,
            letterSpacing: 2,
            color: '#fafafa', // much lighter
            marginBottom: 0,
            textAlign: 'center',
            textTransform: 'uppercase',
            opacity: 0.92,
            textShadow: '0 0 32px #000, 0 0 4px #fff8, 0 2px 0 #222',
            userSelect: 'none',
            filter: 'blur(0.5px)',
          }}
        >
          CIV 5
        </div>
        <div
          style={{
            fontSize: 38,
            fontWeight: 700,
            color: '#e0e0e0',
            letterSpacing: 2,
            marginBottom: 40,
            textAlign: 'center',
            textTransform: 'uppercase',
            opacity: 0.7,
            userSelect: 'none',
            textShadow: '0 0 12px #000, 0 0 2px #fff8',
          }}
        >
          [NO QUIT]
        </div>
        <div
          style={{
            background: '#232323',
            borderRadius: 8,
            boxShadow: '0 2px 24px #000b',
            padding: '32px 36px',
            margin: '0 auto',
            minWidth: 320,
            maxWidth: '90vw',
            textAlign: 'center',
            border: '1.5px solid #444',
            opacity: 0.97,
          }}
        >
          <button
            onClick={joinDiscord}
            style={{
              background: 'linear-gradient(90deg, #444 60%, #222 100%)',
              color: '#fff',
              border: 'none',
              borderRadius: 4,
              fontFamily: 'inherit',
              fontSize: 22,
              padding: '12px 48px',
              cursor: 'pointer',
              fontWeight: 700,
              marginTop: 8,
              boxShadow: '0 2px 8px #0003',
              transition: 'background 0.2s, color 0.2s',
              outline: 'none',
              textTransform: 'uppercase',
              letterSpacing: 2,
              textShadow: '0 0 6px #000, 0 0 2px #fff8',
            }}
            onMouseOver={e => {
              e.target.style.background = 'linear-gradient(90deg, #222 60%, #111 100%)';
              e.target.style.color = '#ffe';
            }}
            onMouseOut={e => {
              e.target.style.background = 'linear-gradient(90deg, #444 60%, #222 100%)';
              e.target.style.color = '#fff';
            }}
          >
            Join Discord
          </button>
        </div>
      </div>
    </>
  );
}

export default App;
